<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,messageOf} from '@/api/client'
import {useAuthStore} from '@/stores/auth'
interface User{ID:string;Username:string;Email:string;Role:string;Disabled:boolean;CreatedAt:string}
const auth=useAuthStore(),users=ref<User[]>([]),query=ref(''),offset=ref(0),total=ref(0),busy=ref(false),error=ref(''),notice=ref('')
async function load(){busy.value=true;error.value='';try{const {data}=await api.get('/admin/users',{params:{q:query.value,offset:offset.value}});users.value=data.Users;total.value=data.Total}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
async function change(u:User,role:string,disabled:boolean){if(!confirm(`确认修改 ${u.Username}：${role==='admin'?'管理员':'普通用户'}，${disabled?'停用':'启用'}？`))return;busy.value=true;notice.value='';try{await api.patch(`/admin/users/${u.ID}`,{Role:role,Disabled:disabled});notice.value='用户权限已更新';await load()}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div><header class="page-head"><div><h1>用户管理</h1><p>角色和停用状态由后端逐次校验；不能停用自己，系统至少保留一位可用管理员。</p></div></header><p v-if="error" class="notice error">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><form class="card toolbar-actions" @submit.prevent="offset=0;load()"><input v-model="query" aria-label="搜索用户名或邮箱" placeholder="搜索用户名或邮箱"/><button class="primary" :disabled="busy">搜索</button><span>共 {{total}} 位用户</span></form><section class="card section"><div class="list"><article v-for="u in users" :key="u.ID" class="list-item"><div class="grow"><b>{{u.Username}}</b><p>{{u.Email}}</p><small>{{new Date(u.CreatedAt).toLocaleString()}}</small></div><span class="pill">{{u.Role==='admin'?'管理员':'普通用户'}} · {{u.Disabled?'已停用':'正常'}}</span><button class="secondary" :disabled="busy||u.ID===auth.user?.id" @click="change(u,u.Role==='admin'?'student':'admin',u.Disabled)">{{u.Role==='admin'?'取消管理权限':'设为管理员'}}</button><button class="secondary" :disabled="busy||u.ID===auth.user?.id" @click="change(u,u.Role,!u.Disabled)">{{u.Disabled?'恢复账号':'停用账号'}}</button></article></div><p v-if="!users.length">没有匹配的用户。</p><div class="toolbar-actions"><button class="secondary" :disabled="busy||offset===0" @click="offset-=50;load()">上一页</button><button class="secondary" :disabled="busy||offset+50>=total" @click="offset+=50;load()">下一页</button></div></section></div></template>
